Object.entries({"fr": {"On iPhone, Safari erases saved books after 7 days without a visit. Install the app on your home screen to keep them.": "Sur iPhone, Safari efface les livres enregistrés après 7 jours sans visite. Installez l’appli sur l’écran d’accueil pour les garder.", "📲 Install": "📲 Installer"}, "es": {"On iPhone, Safari erases saved books after 7 days without a visit. Install the app on your home screen to keep them.": "En iPhone, Safari borra los libros guardados tras 7 días sin visitas. Instala la app en la pantalla de inicio para conservarlos.", "📲 Install": "📲 Instalar"}, "ht": {"On iPhone, Safari erases saved books after 7 days without a visit. Install the app on your home screen to keep them.": "Sou iPhone, Safari efase liv ou yo apre 7 jou san vizit. Enstale aplikasyon an sou ekran dakèy ou pou kenbe yo.", "📲 Install": "📲 Enstale"}, "pt": {"On iPhone, Safari erases saved books after 7 days without a visit. Install the app on your home screen to keep them.": "No iPhone, o Safari apaga os livros guardados após 7 dias sem visita. Instale a app no ecrã principal para os manter.", "📲 Install": "📲 Instalar"}, "de": {"On iPhone, Safari erases saved books after 7 days without a visit. Install the app on your home screen to keep them.": "Auf dem iPhone löscht Safari gespeicherte Bücher nach 7 Tagen ohne Besuch. Installiere die App auf dem Home-Bildschirm, um sie zu behalten.", "📲 Install": "📲 Installieren"}, "it": {"On iPhone, Safari erases saved books after 7 days without a visit. Install the app on your home screen to keep them.": "Su iPhone, Safari cancella i libri salvati dopo 7 giorni senza visite. Installa l’app nella schermata Home per conservarli.", "📲 Install": "📲 Installa"}}).forEach(([l,o])=>{TR[l]=Object.assign(TR[l]||{},o)});
